ANTAL_ELEVER = 3
ANTAL_HOPP = 3

class Elev:
  def __init__ (self, namn):
    self.namn = namn
    self.hopp = []

  def __str__ (self):
    sträng = self.namn + " hoppade: " 
    for hopp in self.hopp:
        sträng += str(hopp) +  ", "
    return sträng[0:-2]

  def hoppat(self, antal_hopp):
    for i in range(antal_hopp):
        hoppet = float(input("Hur långt var hopp " + str(i + 1) + "? "))
        self.hopp.append(hoppet)

  def __lt__ (self, other):
    if self.namn < other.namn:
        return True
    else:
        return False

  def längsta_hoppet(self):
    längsta = self.hopp[0]
    for hoppet in self.hopp:
      if hoppet > längsta:
        längsta = hoppet
    print(self.namn + " hoppade som längst " + str(längsta) + " meter.")

def skriv_ut(objekt_lista):
  for objekt in objekt_lista:
    print(objekt)

def läsa_in():
  elever = []
  for i in range(ANTAL_ELEVER):
    namn = input("Vad heter elev " + str(i+1) + "?")
    elev = Elev(namn)
    elev.hoppat(ANTAL_HOPP)
    elever.append(elev)
  return elever

def meny(elever):

  print("""1. Lägga till en elev och dess hopp.
2. Skriva ut en sorterad lista med elever och dess hopp.
3. Skriva ut längsta hoppet.
4. Skriva ut sista hoppet en elev gjorde
5. Avsluta
  """)
  val = input("Vad vill du göra? ")
  while val != 5:
    if val == "1":
      namn = input("Vad heter elev " + str(len(elever)+1) + "?")
      elev = Elev(namn)
      elev.hoppat(ANTAL_HOPP)
      elever.append(elev)

    elif val == "2":
      elever.sort()
      skriv_ut(elever)

    elif val == "3":
      for elev in elever:
        elev.längsta_hoppet()

    elif val =="4":
      for elev in elever:
        print(elev.namn + " hoppade " + str(elev.hopp[-1]) + " på sitt sista hopp.")

    elif val =="5":
      print("Hejdå")
      break

    else:
      print("Nej det var inte ett val, försök igen.")
    val = input("Vad vill du göra? ")

def huvudprogram():
  print("Välkommen till programmet som håller koll på elevernas längdhopp.")
  alla_elever = läsa_in()
  meny(alla_elever)

huvudprogram()
